function criarCardProjeto(e){let n="";return e.detalhes&&(n=`<br>\n      <input type="checkbox" id="modal-${e.id}" class="modal-toggle-input">\n      <label for="modal-${e.id}" class="modal-trigger">Ver mais detalhes</label>\n      <div class="modal-overlay">\n        <div class="modal-box">\n          <h3>${e.titulo}</h3>\n          <p>${e.detalhes}</p>\n          <label for="modal-${e.id}" class="modal-close">Fechar</label>\n        </div>\n      </div>`),`\n    <article id="${e.id}">\n      <h3>${e.titulo}</h3>\n      <p>${e.descricao}</p>\n      <span class="badge ${e.classeStatus}">${e.status}</span>\n      ${n}\n    </article>`}function limparTexto(e){return String(e).replace(/</g,"&lt;")}function criarListaCadastros(){const e=lerCadastros();if(0===e.length)return"";return`\n    <section id="lista-cadastros">\n      <h2>Cadastros enviados</h2>\n      <ul>${e.map(function(e){return`<li>${limparTexto(e.nome)} - ${limparTexto(e.email)}\n      (${limparTexto(e.cidade)}/${limparTexto(e.estado)})\n      - enviado em ${e.data}</li>`}).join("")}</ul>\n      <button type="button" id="limpar-cadastros">Limpar lista</button>\n    </section>`}const TEMPLATES={"/":{titulo:"Sobre a ONG",subtitulo:"Conheça nossa organização, nossa missão e nossos objetivos.",html:function(){return'\n    <section class="section-primary">\n      <h2>Quem somos</h2>\n      <p>Nossa organização atua em iniciativas sociais e comunitárias, buscando incentivar a participação e a transformação social.</p>\n      <img src="../imagens/ong.png" alt="Equipe da ONG reunida em uma atividade comunitária">\n    </section>\n\n    <section class="section-secondary">\n      <h2>Contato</h2>\n      <p>Entre em contato conosco para saber mais sobre nosso trabalho.</p>\n      <address>\n        E-mail: contato@ong.org<br>\n        Telefone: (11) 0000-0000\n      </address>\n    </section>'}},"/projetos":{titulo:"Projetos da ONG",subtitulo:"Conheça nossas iniciativas e descubra como participar.",html:function(){return`\n    <section>\n      <h2>Projetos sociais</h2>\n\n      <div class="projetos-grid">\n        ${PROJETOS.map(criarCardProjeto).join("")}\n      </div>\n    </section>\n\n    <section>\n      <h2>Como contribuir</h2>\n      <p>Você pode conhecer nossos projetos, realizar uma doação ou cadastrar-se para participar como voluntário.</p>\n      <p><a href="#/cadastro">Acessar formulário de cadastro</a></p>\n    </section>`}},"/cadastro":{titulo:"Cadastro",subtitulo:"Preencha seus dados para estabelecer contato com a ONG.",html:function(){return`\n    <div class="alert alert-info">\n      Preencha todos os campos abaixo. Os dados são usados só pra entrarmos em contato com você.\n    </div>\n\n    <div id="mensagem-form" aria-live="polite"></div>\n\n    <form action="#" method="post" novalidate>\n      <fieldset>\n        <legend>Dados pessoais</legend>\n\n        <div class="form-grid">\n          <div class="field">\n            <label for="nome">Nome completo:</label>\n            <input type="text" id="nome" name="nome" required>\n          </div>\n\n          <div class="field field-half">\n            <label for="email">E-mail:</label>\n            <input type="email" id="email" name="email" required>\n          </div>\n\n          <div class="field field-half">\n            <label for="nascimento">Data de nascimento:</label>\n            <input type="date" id="nascimento" name="nascimento" required>\n          </div>\n\n          <div class="field">\n            <label for="cpf">CPF:</label>\n            <input type="text" id="cpf" name="cpf"\n                   pattern="[0-9]{3}\\.[0-9]{3}\\.[0-9]{3}-[0-9]{2}"\n                   placeholder="000.000.000-00" required>\n          </div>\n        </div>\n      </fieldset>\n\n      <fieldset>\n        <legend>Contato e endereço</legend>\n\n        <div class="form-grid">\n          <div class="field field-half">\n            <label for="telefone">Telefone:</label>\n            <input type="tel" id="telefone" name="telefone"\n                   pattern="\\([0-9]{2}\\) [0-9]{5}-[0-9]{4}"\n                   placeholder="(11) 99999-9999" required>\n          </div>\n\n          <div class="field field-half">\n            <label for="cep">CEP:</label>\n            <input type="text" id="cep" name="cep"\n                   pattern="[0-9]{5}-[0-9]{3}"\n                   placeholder="00000-000" required>\n          </div>\n\n          <div class="field field-half">\n            <label for="endereco">Endereço:</label>\n            <input type="text" id="endereco" name="endereco" required>\n          </div>\n\n          <div class="field field-half">\n            <label for="cidade">Cidade:</label>\n            <input type="text" id="cidade" name="cidade" required>\n          </div>\n\n          <div class="field field-half">\n            <label for="estado">Estado:</label>\n            <input type="text" id="estado" name="estado" maxlength="2" required>\n          </div>\n        </div>\n      </fieldset>\n\n      <div class="form-actions">\n        <button type="submit">Enviar cadastro</button>\n      </div>\n    </form>\n\n    ${criarListaCadastros()}`}}};